import { reactive } from 'vue'

const STORAGE_KEY = 'hy.locale'
export const DEFAULT_LOCALE = 'zh-CN'

export const localeOptions = [
  { id: 'zh-CN', label: '简体中文', short: '中', htmlLang: 'zh-CN' },
  { id: 'zh-TW', label: '繁體中文', short: '繁', htmlLang: 'zh-TW' },
  { id: 'en', label: 'English', short: 'EN', htmlLang: 'en' },
  { id: 'ja', label: '日本語', short: '日', htmlLang: 'ja' },
  { id: 'de', label: 'Deutsch', short: 'DE', htmlLang: 'de' },
  { id: 'ko', label: '한국어', short: '한', htmlLang: 'ko' },
  { id: 'fr', label: 'Français', short: 'FR', htmlLang: 'fr' }
]

export const i18n = reactive({
  locale: localStorage.getItem(STORAGE_KEY) || DEFAULT_LOCALE
})

function normalizeLocale(value) {
  return localeOptions.some((item) => item.id === value) ? value : DEFAULT_LOCALE
}

export function setLocale(id, persist = true) {
  const locale = normalizeLocale(id)
  i18n.locale = locale
  if (persist) localStorage.setItem(STORAGE_KEY, locale)
  document.documentElement.lang = locale
  document.title = t('app.title')
}

export function t(key, params = {}, fallback = null) {
  const table = messages[i18n.locale] || messages.en
  let value = table[key]
  if (value === undefined) value = messages.en?.[key]
  if (value === undefined) value = messages[DEFAULT_LOCALE][key]
  if (value === undefined) return fallback === null ? key : fallback
  return value.replace(/\{(\w+)\}/g, (_, name) => (params[name] !== undefined ? params[name] : `{${name}}`))
}

export function te(key) {
  return messages[i18n.locale]?.[key] !== undefined
    || messages.en?.[key] !== undefined
    || messages[DEFAULT_LOCALE][key] !== undefined
}

export function tr(key, fallback, params = {}) {
  return t(key, params, fallback)
}

const DEFAULT_SESSION_TITLES = new Set([
  '',
  'New task',
  'New coding task',
  'New plan',
  'New storyboard',
  'Robot task',
  'New conversation',
  'Untitled',
  '新建任务',
  '新任务',
  '新对话',
  '新会话',
  '新建会话',
  '未命名会话',
  '新方案',
  '新分镜',
  '机器人任务'
])

export function isDefaultSessionTitle(title) {
  return DEFAULT_SESSION_TITLES.has(String(title || '').trim())
}

export function summarizeSessionTitle(text) {
  let value = String(text || '').replace(/```[\s\S]*?```/g, ' ').replace(/\s+/g, ' ').trim()
  if (!value) return ''
  value = value.replace(/^(?:你好|您好|嗨|哈喽|hi|hello|hey)[，,。.!！?？\s]*/i, '')
  value = value.replace(/^(?:请|麻烦|帮我|帮忙|给我|please|can you|could you|help me)\s*/i, '')
  value = value.replace(/^[\s"'`“”‘’#*\-]+|[\s"'`“”‘’#*\-]+$/g, '').trim()
  if (!value) return ''
  const limit = /[\u4e00-\u9fff]/.test(value) ? 24 : 56
  return value.length > limit ? `${value.slice(0, limit).trimEnd()}…` : value
}

export function sessionTitle(session) {
  if (!session) return t('session.untitled')
  const raw = String(session.title || '').trim()
  if (raw && !isDefaultSessionTitle(raw)) return raw
  return summarizeSessionTitle(session.first_question || '') || t('session.untitled')
}

export function kindLabel(kind) {
  return t(`kind.${kind || 'auto'}`, {}, kind || 'auto')
}

export function statusLabel(status) {
  const map = {
    waiting_input: 'status.approval',
    cancelled: 'status.stopped',
    stale: 'status.stalled',
    ok: 'status.healthy'
  }
  return t(map[status] || `status.${status}`, {}, status)
}

export function pluginDescription(name, fallback) {
  return t(`plugin.desc.${name}`, {}, fallback || '')
}

export function skillTitle(skill) {
  if (!skill) return ''
  return t(`skill.${skill.name}.title`, {}, skill.title || skill.name)
}

export function skillDescription(skill) {
  if (!skill) return ''
  return t(`skill.${skill.name}.desc`, {}, skill.description || '')
}

export function formatRelativeTime(value) {
  if (!value) return ''
  const date = new Date(String(value).replace(' ', 'T'))
  if (Number.isNaN(date.getTime())) return ''
  const diff = Date.now() - date.getTime()
  if (diff < 60000) return t('time.now')
  if (diff < 3600000) return t('time.minutesShort', { n: Math.floor(diff / 60000) })
  if (diff < 86400000) return t('time.hoursShort', { n: Math.floor(diff / 3600000) })
  return `${date.getMonth() + 1}/${date.getDate()}`
}

